function responseHeaders(asset) {
  const headers = {
    'Content-Type': asset.contentType,
    'Cache-Control': asset.cacheControl,
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'geolocation=(), microphone=(), camera=()',
  };
  return headers;
}

function responseBody(asset) {
  if (asset.encoding !== 'base64-gzip') return asset.body;
  const binary = atob(asset.body);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/config') {
      return Response.json(
        { googleMapsApiKey: env.GOOGLE_MAPS_API_KEY || '' },
        {
          headers: {
            'Cache-Control': 'no-store, max-age=0',
            'X-Content-Type-Options': 'nosniff',
          },
        },
      );
    }

    const asset = assets.get(url.pathname);
    if (!asset) {
      return new Response('Não encontrado', {
        status: 404,
        headers: { 'Content-Type': 'text/plain; charset=utf-8' },
      });
    }

    if (request.method === 'HEAD') {
      return new Response(null, { headers: responseHeaders(asset) });
    }

    if (request.method !== 'GET') {
      return new Response('Método não permitido', {
        status: 405,
        headers: { Allow: 'GET, HEAD', 'Content-Type': 'text/plain; charset=utf-8' },
      });
    }

    return new Response(responseBody(asset), { headers: responseHeaders(asset) });
  },
};
